def choose_move(observation):
    # Simple deterministic: move toward closest resource if available, else stay or move toward center.
    pos = observation.get('self_position', (0, 0))
    rx, ry = pos
    dx = 0
    dy = 0

    resources = observation.get('resources', [])
    if resources:
        best = None
        best_dist = None
        for r in resources:
            x = r.get('x', 0)
            y = r.get('y', 0)
            d = abs(x - rx) + abs(y - ry)
            if best_dist is None or d < best_dist:
                best_dist = d
                best = (x, y)
        if best is not None:
            tx, ty = best
            if tx > rx:
                dx = 1
            elif tx < rx:
                dx = -1
            else:
                dx = 0
            if ty > ry:
                dy = 1
            elif ty < ry:
                dy = -1
            else:
                dy = 0
            return [dx, dy]

    # If no resources, move toward center of grid if known
    width = observation.get('grid_width', 0)
    height = observation.get('grid_height', 0)
    cx = width // 2
    cy = height // 2
    if width and height:
        if cx > rx:
            dx = 1
        elif cx < rx:
            dx = -1
        else:
            dx = 0
        if cy > ry:
            dy = 1
        elif cy < ry:
            dy = -1
        else:
            dy = 0
        return [dx, dy]

    # Fallback: stay
    return [0, 0]
